     9	    public static Message save(Message message) throws SQLException {
    10	        String sql = """
    11	            INSERT INTO messages (channel, recipient_email, subject, body)
    12	            VALUES (?, ?, ?, ?)
    13	            """;
    14	
    15	        try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql,
    16	             Statement.RETURN_GENERATED_KEYS)) {
    17	            stmt.setString(1, message.channel);
    18	            stmt.setString(2, message.to);
    19	            stmt.setString(3, message.subject);
    20	            stmt.setString(4, message.body);
    21	
    22	            stmt.executeUpdate();
    23	
    24	            try (ResultSet rs = stmt.getGeneratedKeys()) {
    25	                if (rs.next()) {
    26	                    message.id = rs.getLong(1);
    27	                }
    28	            }
    29	        }
    30	        return message;
    31	    }
    32	
    33	    public static List<Message> findAll() throws SQLException {
    34	        List<Message> messages = new ArrayList<>();
    35	        String sql = """
    36	            SELECT id, channel, recipient_email, subject, body
    37	            FROM messages
    38	            ORDER BY id
    39	            """;
    40	
    41	        try (Statement stmt = Database.getConnection().createStatement();
    42	             ResultSet rs = stmt.executeQuery(sql)) {
