    10	public class ReservationDao {
    11	    public static Reservation save(Reservation reservation) throws SQLException {
    12	        if (reservation.id == null) {
    13	            return insert(reservation);
    14	        } else {
    15	            update(reservation);
    16	            return reservation;
    17	        }
    18	    }
    19	
    20	    private static Reservation insert(Reservation reservation) throws SQLException {
    21	        String sql = """
    22	            INSERT INTO reservations
    23	            (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests,
    24	             rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    25	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    26	            """;
    27	
    28	        try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql,
    29	             Statement.RETURN_GENERATED_KEYS)) {
    30	            stmt.setInt(1, reservation.roomNumber);
    31	            stmt.setString(2, reservation.guestName);
    32	            stmt.setString(3, reservation.guestEmail);
    33	            stmt.setString(4, reservation.guestCpf);
    34	            stmt.setDate(5, java.sql.Date.valueOf(reservation.checkIn));
    35	            stmt.setDate(6, java.sql.Date.valueOf(reservation.checkOut));
    36	            stmt.setInt(7, reservation.guests);
    37	            stmt.setString(8, reservation.ratePlan.toString());
    38	            stmt.setInt(9, reservation.nights);
    39	            stmt.setBigDecimal(10, reservation.subtotal);
    40	            stmt.setBigDecimal(11, reservation.discount);
    41	            stmt.setBigDecimal(12, reservation.total);
    42	            stmt.setString(13, reservation.status.toString());
    43	            stmt.setBigDecimal(14, reservation.amountPaid);
    44	            stmt.setNull(15, Types.NUMERIC);
    45	
    46	            stmt.executeUpdate();
    47	
    48	            try (ResultSet rs = stmt.getGeneratedKeys()) {
    49	                if (rs.next()) {
    50	                    reservation.id = rs.getLong(1);
    51	                }
    52	            }
    53	        }
    54	        return reservation;
    55	    }
    56	
    57	    private static void update(Reservation reservation) throws SQLException {
    58	        String sql = """
    59	            UPDATE reservations
    60	            SET status = ?, amount_paid = ?, refund = ?
    61	            WHERE id = ?
    62	            """;
    63	
    64	        try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
    65	            stmt.setString(1, reservation.status.toString());
    66	            stmt.setBigDecimal(2, reservation.amountPaid);
    67	            if (reservation.refund != null) {
    68	                stmt.setBigDecimal(3, reservation.refund);
    69	            } else {
    70	                stmt.setNull(3, Types.NUMERIC);
    71	            }
    72	            stmt.setLong(4, reservation.id);
    73	            stmt.executeUpdate();
    74	        }
    75	    }
