   124	            FROM reservations
   125	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
   126	                AND check_in <= ? AND check_out > ?
   127	            ORDER BY room_number
   128	            """;
   129	
   130	        try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
   131	            stmt.setDate(1, java.sql.Date.valueOf(date));
   132	            stmt.setDate(2, java.sql.Date.valueOf(date));
   133	            try (ResultSet rs = stmt.executeQuery()) {
   134	                while (rs.next()) {
