   142	    public static List<Reservation> findForRevenueReport(LocalDate monthStart, LocalDate monthEnd)
   143	            throws SQLException {
   144	        List<Reservation> reservations = new ArrayList<>();
   145	        String sql = """
   146	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
   147	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
   148	            FROM reservations
   149	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
   150	                AND check_in >= ? AND check_in < ?
   151	            ORDER BY check_in, id
   152	            """;
   153	
   154	        try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
   155	            stmt.setDate(1, java.sql.Date.valueOf(monthStart));
   156	            stmt.setDate(2, java.sql.Date.valueOf(monthEnd));
   157	            try (ResultSet rs = stmt.executeQuery()) {
   158	                while (rs.next()) {
   159	                    reservations.add(mapReservation(rs));
   160	                }
   161	            }
   162	        }
   163	        return reservations;
   164	    }
   165	
   166	    private static Reservation mapReservation(ResultSet rs) throws SQLException {
   167	        Reservation res = new Reservation();
   168	        res.id = rs.getLong("id");
   169	        res.roomNumber = rs.getInt("room_number");
   170	        res.guestName = rs.getString("guest_name");
   171	        res.guestEmail = rs.getString("guest_email");
   172	        res.guestCpf = rs.getString("guest_cpf");
   173	        res.checkIn = rs.getDate("check_in").toLocalDate();
   174	        res.checkOut = rs.getDate("check_out").toLocalDate();
   175	        res.guests = rs.getInt("guests");
   176	        res.ratePlan = RatePlan.valueOf(rs.getString("rate_plan"));
   177	        res.nights = rs.getInt("nights");
   178	        res.subtotal = rs.getBigDecimal("subtotal");
   179	        res.discount = rs.getBigDecimal("discount");
   180	        res.total = rs.getBigDecimal("total");
   181	        res.status = ReservationStatus.valueOf(rs.getString("status"));
   182	        res.amountPaid = rs.getBigDecimal("amount_paid");
   183	        res.refund = rs.getBigDecimal("refund");
   184	        return res;
   185	    }
   186	}
