   109	
   110	        int standardCount = 0;
   111	        BigDecimal standardAmount = BigDecimal.ZERO;
   112	        int nonRefundableCount = 0;
   113	        BigDecimal nonRefundableAmount = BigDecimal.ZERO;
   114	
   115	        for (Reservation res : reservations) {
   116	            BigDecimal amountPaid = res.amountPaid != null ? res.amountPaid : BigDecimal.ZERO;
   117	            BigDecimal refund = res.refund != null ? res.refund : BigDecimal.ZERO;
   118	            BigDecimal amount = amountPaid.subtract(refund);
   119	
   120	            if (res.ratePlan == RatePlan.STANDARD) {
   121	                standardCount++;
   122	                standardAmount = standardAmount.add(amount);
   123	            } else {
   124	                nonRefundableCount++;
   125	                nonRefundableAmount = nonRefundableAmount.add(amount);
   126	            }
   127	        }
   128	
   129	        StringBuilder csv = new StringBuilder();
