   132	
   133	        csv.append("STANDARD,").append(standardCount).append(",")
   134	           .append(DocumentFormatter.formatCurrencyCsv(standardAmount)).append("\n");
   135	
   136	        csv.append("NON_REFUNDABLE,").append(nonRefundableCount).append(",")
   137	           .append(DocumentFormatter.formatCurrencyCsv(nonRefundableAmount)).append("\n");
   138	
   139	        int totalCount = standardCount + nonRefundableCount;
   140	        BigDecimal totalAmount = standardAmount.add(nonRefundableAmount);
   141	        csv.append("total,").append(totalCount).append(",")
   142	           .append(DocumentFormatter.formatCurrencyCsv(totalAmount)).append("\n");
