    11	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	    private static final NumberFormat CURRENCY_FORMATTER = NumberFormat.getInstance(new Locale("pt", "BR"));
    13	
    14	    static {
    15	        CURRENCY_FORMATTER.setMinimumFractionDigits(2);
    16	        CURRENCY_FORMATTER.setMaximumFractionDigits(2);
    17	    }
    18	
    19	    public static String formatReservationDocument(Reservation reservation, String roomType) {
    20	        StringBuilder sb = new StringBuilder();
    21	        sb.append("Comprovante de reserva nº ").append(reservation.id).append("\n");
    22	        sb.append("Hóspede: ").append(reservation.guestName)
    23	          .append(" (CPF ").append(formatCpf(reservation.guestCpf)).append(")\n");
    24	        sb.append("Quarto: ").append(reservation.roomNumber).append(" (").append(roomType).append(")\n");
    25	        sb.append("Entrada: ").append(formatDate(reservation.checkIn))
    26	          .append(" | Saída: ").append(formatDate(reservation.checkOut))
    27	          .append(" | ").append(reservation.nights).append(reservation.nights == 1 ? " diária" : " diárias").append("\n");
    28	        sb.append("Diárias: ").append(formatCurrency(reservation.subtotal)).append("\n");
    29	
    30	        if (reservation.discount.compareTo(BigDecimal.ZERO) > 0) {
    31	            sb.append("Desconto: ").append(formatCurrency(reservation.discount)).append("\n");
    32	        }
    33	
    34	        sb.append("Total: ").append(formatCurrency(reservation.total)).append("\n");
    35	
    36	        return sb.toString().trim();
    37	    }
    38	
    39	    public static String formatDate(LocalDate date) {
    40	        return date.format(DATE_FORMATTER);
    41	    }
    42	
    43	    public static String formatCurrency(BigDecimal amount) {
    44	        return "R$ " + String.format("%.2f", amount).replace(".", ",");
    45	    }
    46	
    47	    public static String formatCurrencyCsv(BigDecimal amount) {
    48	        return String.format("%.2f", amount);
    49	    }
    50	
    51	    public static String formatCpf(String cpf) {
    52	        if (cpf == null || cpf.length() != 11) return cpf;
    53	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    54	               cpf.substring(6, 9) + "-" + cpf.substring(9);
    55	    }
    56	
    57	    public static String formatDateCsv(LocalDate date) {
    58	        return date.toString();
    59	    }
    60	}
