     1	package com.marealata.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class PriceCalculator {
     8	    private static final BigDecimal NIGHTLY_RATE_STANDARD_101 = new BigDecimal("249.90");
     9	    private static final BigDecimal NIGHTLY_RATE_STANDARD_102 = new BigDecimal("249.90");
    10	    private static final BigDecimal NIGHTLY_RATE_DELUXE_201 = new BigDecimal("389.90");
    11	    private static final BigDecimal NIGHTLY_RATE_DELUXE_202 = new BigDecimal("389.90");
    12	    private static final BigDecimal NIGHTLY_RATE_SUITE_301 = new BigDecimal("579.90");
    13	
    14	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    15	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    16	
    17	    public static BigDecimal getNightlyRate(int roomNumber) {
    18	        return switch (roomNumber) {
    19	            case 101, 102 -> NIGHTLY_RATE_STANDARD_101;
    20	            case 201, 202 -> NIGHTLY_RATE_DELUXE_201;
    21	            case 301 -> NIGHTLY_RATE_SUITE_301;
    22	            default -> throw new IllegalArgumentException("Invalid room number: " + roomNumber);
    23	        };
    24	    }
    25	
    26	    public static boolean isHighSeason(LocalDate date) {
    27	        int month = date.getMonthValue();
    28	        int dayOfMonth = date.getDayOfMonth();
    29	
    30	        if (month == 7) return true;
    31	        if (month == 12) return true;
    32	        if (month == 1) return true;
    33	        if (month == 2) return true;
    34	
    35	        return false;
    36	    }
    37	
    38	    public static BigDecimal calculateNightlyPrice(int roomNumber, LocalDate date) {
    39	        BigDecimal baseRate = getNightlyRate(roomNumber);
    40	        if (isHighSeason(date)) {
    41	            baseRate = baseRate.multiply(HIGH_SEASON_MULTIPLIER);
    42	        }
    43	        return round(baseRate);
    44	    }
    45	
    46	    public static BigDecimal calculateSubtotal(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    47	        BigDecimal subtotal = BigDecimal.ZERO;
    48	        LocalDate current = checkIn;
    49	        while (current.isBefore(checkOut)) {
    50	            subtotal = subtotal.add(calculateNightlyPrice(roomNumber, current));
    51	            current = current.plusDays(1);
    52	        }
    53	        return round(subtotal);
    54	    }
    55	
    56	    public static BigDecimal calculateDiscount(BigDecimal subtotal, com.marealata.model.RatePlan ratePlan) {
    57	        if (ratePlan == com.marealata.model.RatePlan.NON_REFUNDABLE) {
    58	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
    59	        }
    60	        return BigDecimal.ZERO;
    61	    }
    62	
    63	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    64	        return round(subtotal.subtract(discount));
    65	    }
    66	
    67	    public static BigDecimal round(BigDecimal value) {
    68	        return value.setScale(2, RoundingMode.HALF_EVEN);
    69	    }
    70	
    71	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    72	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    73	    }
    74	}

